import { useState } from "react";
import { useUser } from "../context/UserContext";
import Sidebar from "../components/Sidebar";
import Footer from "../components/Footer";
import styles from "./Dashboard.module.css";
import { ResponsiveContainer, BarChart, XAxis, YAxis, Tooltip, Bar, PieChart, Pie, Cell, Legend } from "recharts";

const Dashboard = () => {
  const { userData, loading } = useUser();
  const [activeIndex, setActiveIndex] = useState(null);
  

  if (loading) return <p>Chargement des données...</p>;
  if (!userData) return <p>Impossible de récupérer les informations utilisateur.</p>;

  
  const { profile, statistics, session, startDate, endDate } = userData;


  // Transformer les dates en format lisible
const formatDate = (dateStr) => {
  if (!dateStr) return "";
  const date = new Date(dateStr);
  if (isNaN(date)) return "";
  return date.toLocaleDateString("fr-FR", { day: "2-digit", month: "short" });
};

// Dans ton Dashboard
const startDisplay = formatDate(startDateFromBackend || startWeek);
const endDisplay = formatDate(endDateFromBackend || endWeek);
const displayDateRange = startDisplay && endDisplay ? `${startDisplay} - ${endDisplay}` : "Date non disponible";
  const weeklyDistanceData = [
  { week: "S1", km: 42 },
  { week: "S2", km: 55 },
  { week: "S3", km: 38 },
  { week: "S4", km: 60 },
];

  const heartRateData = [
    { name: "Repos", bpm: 70 },
    { name: "Effort", bpm: 140 },
  ];

  const donutData = [
    { name: "Réalisé", value: 4 },
    { name: "Restant", value: 2 },
  ];

  
  const COLORS = ["#4e73df", "#e0e0e0"];
  // ✅ Fonction pour générer les ticks Y tous les 10
  const getYTicks = () => {
    const maxKm = Math.max(...weeklyDistanceData.map(d => d.km));
    const ticks = [];
    for (let i = 0; i <= maxKm + 10; i += 10) {
      ticks.push(i);
    }
    return ticks;
  };

  
const CustomTooltip = ({ active, payload, label }) => {
  if (active && payload && payload.length) {
    const km = payload[0].value;
    return (
       <div className={styles.customTooltip}>
        <div className={styles.tooltipLabel}>01/06 au 07/06</div>
        <div className={styles.tooltipValue}>{km} km</div>
      </div>
    );
  }

  return null;
};


  return (
    <div className={styles.container}>
      <Sidebar />
      <div className={styles.main}>
        {/* Section 1 – Profil */}
        <section className={`${styles.section} ${styles.profileSection}`}>
          <div className={styles.profileCard}>
            <img
              src={profile.profilePicture || "/avatar.png"}
              alt="Profil"
              className={styles.photo}
            />
            <div className={styles.userInfo}>
              <h2 className={styles.name}>
                {profile.firstName} {profile.lastName}
              </h2>
              <p className={styles.memberSince}>
                Membre depuis {profile.createdAt}
              </p>
            </div>
          </div>

          <div className={styles.distanceWrapper}>
            <p className={styles.label}>Distance totale</p>
            <div className={styles.distanceCard}>
              <span className={styles.icon}>🏊‍♂️</span>
              <h2 className={styles.value}>{statistics.totalDistance} km</h2>
            </div>
          </div>
        </section>

        {/* Section 2 – Performances */}
        <section className={`${styles.section} ${styles.performanceSection}`}>
          <h3>Vos dernières performances</h3>
          <div className={styles.graphs}>
            <div className={styles.graphCard}>
              {/* Header */}
              <div className={styles.graphHeader}>
                <h4 className={styles.titleBlue}>Km en moyenne</h4>
                <div className={styles.periodSelector}>
                  <button>{"<"}</button>
                  <span>{displayDateRange}</span> 
                  <button>{">"}</button>
                </div>
              </div>

              <p className={styles.summary}>
                Total des kilomètres sur les 4 dernières semaines
              </p>
{/* Graph Fréquence cardiaque */}
              <div className={styles.graph}>
                <ResponsiveContainer>
                  <BarChart data={weeklyDistanceData} width={500} height={300} >
                    <XAxis tickLine={false} tick={{ fontSize: 12, fill: "#666", dy: 10  }} padding={{ left: 10, right: 10 }} dataKey="week" />
                    <YAxis tickLine={false} ticks={getYTicks()} tick={{ fontSize: 12, fill: "#666", dx: -10, dy: -10   }}  />
                    <Tooltip content={<CustomTooltip />} />
                    <Legend verticalAlign="bottom" align="left" wrapperStyle={{ left: 30 }}iconType="circle" iconSize={5} formatter={(value, entry, index) => (
    <span style={{ color: "#666", fontSize: 12 }}>{value}</span> // couleur du texte
  )} />
                    <Bar dataKey="km" fill="#0b23f4"  barSize={12} radius={[8, 8, 8, 8]}            
                      onMouseEnter={(data, index) => setActiveIndex(index)}
                      onMouseLeave={() => setActiveIndex(null)}
                    >
                      {weeklyDistanceData.map((entry, index) => (
                        <Cell
                          key={`cell-${index}`}
                          fill={index === activeIndex ? "#0b23f4" : "#b6bdfc"} // hover color
                        />
                      ))}
                    </Bar>
                  
                  </BarChart>
                </ResponsiveContainer>
              </div>


              

            </div>

            <div className={styles.graphCard}>
              <div className={styles.graphHeader}>
                <h4 className={styles.titleRed}>Fréquence cardiaque</h4>
                <div className={styles.periodSelector}>
                  <button>{"<"}</button>
                  <span>28 mai - 04 juin</span>
                  <button>{">"}</button>
                </div>
              </div>

              <p className={styles.summary}>Fréquence cardiaque moyenne</p>
{/* Graph distance moyenne */}
                  <div className={styles.graph}>
                    <ResponsiveContainer>
                      <BarChart data={heartRateData}>
                        <XAxis dataKey="name" />
                        <YAxis />
                        <Tooltip />
                        <Bar dataKey="bpm" fill="#e74a3b" radius={[6, 6, 0, 0]} />
                      </BarChart>
                    </ResponsiveContainer>
                  </div>

              <div className={styles.legend}>
                <span className={styles.legendItem}>Repos</span>
                <span className={styles.legendItem}>Effort</span>
              </div>
            </div>
          </div>
        </section>

        {/* Section 3 – Semaine */}
        <section className={`${styles.section} ${styles.weekSection}`}>
          <h3>Cette semaine du 01/02 au 07/02</h3>

          <div className={styles.weekStats}>
            <div className={styles.donutCard}>
              <div className={styles.donutHeader}>
                <span className={styles.donutTitle}>Objectif de 6</span>
                <span className={styles.donutValue}>4</span>
              </div>
              <p className={styles.donutLabel}>Courses hebdomadaires réalisées</p>
{/* Graph donut*/}
              <div className={styles.donut}>
                  <ResponsiveContainer>
                    <PieChart>
                      <Pie
                        data={donutData}
                        dataKey="value"
                        nameKey="name"
                        cx="50%"
                        cy="50%"
                        innerRadius={60}
                        outerRadius={80}
                        startAngle={90}
                        endAngle={-270}
                      >
                        {donutData.map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                        ))}
                      </Pie>
                      <Tooltip />
                    </PieChart>
                  </ResponsiveContainer>
              </div>
            </div>

            <div className={styles.details}>
              <div className={styles.detailCard}>
                <p className={styles.detailTitleBlue}>Durée activité</p>
                <p className={styles.detailValue}>{statistics.totalDuration} min</p>
              </div>
              <div className={styles.detailCard}>
                <p className={styles.detailTitleBlue}>Distance</p>
                <p className={styles.detailValueRed}>{statistics.totalDistance} km</p>
              </div>
            </div>
          </div>
        </section>
      </div>

      <Footer />
    </div>
  );
};

export default Dashboard;
